             backup_text =
               {x|type Plant = String in
type Grove = [[Plant]] in
type Row = Int in
type Col = Int in

type Model = (
grove = Grove,
currentSeed = Plant,
seedInventory = [Plant]
) in

type Action =
+ SelectSeed(Int)
+ PlantSeed(Row, Col)
+ Uproot(Row, Col)
+ ClearGrove
+ PlantRow(Row)
# TODO: Add PlantCol(Col) here #
in

let init: Model = (
grove = [
["", "", ""],
["", "", ""],
["", "", ""]
],
currentSeed = "🌱",
seedInventory = ["🌱", "🌿", "🍄", "☘️", "🌸"]
) in

let setCell(grove: Grove, row: Row, col: Col, plant: Plant): Grove =
mapi(grove, fun (i, r) ->
if i == row
then mapi(r, fun (j, c) -> if j == col then plant else c)
else r)
in

let setRow(grove: Grove, targetRow: Row, plant: Plant): Grove =
mapi(grove, fun (i, row) ->
if i == targetRow
then map(row, fun _ -> plant)
else row)
in

